import {gardenSettings} from './garden-facets.mjs';
import * as T from './vendor/three.module.js';
import {cameraOwnsPointer} from './vendor/sandbox-camera.mjs';
import {TILE_CHOICES,SCENE_GENERATORS,multiHexIcon,tileCenter,frontier} from './tile-expansion.mjs';
const descriptions={moon:'Moonbase · colonists, science missions, water, power and food production.',ranch:'Ranch · household, animals and daily farm life.',paddock:'Paddock · livestock enclosures and shelter.','sugar-shack':'Maple sugar shack · sightseeing and a leisure bonus for neighboring tiles.',crop:'Garden · cultivated growing beds and working paths.',meadow:'Meadow · open habitat and vegetation.'};
export function createTileChooser({preview,allowed,scene,camera,orbit,canvas,getBoard}){
 const launch=document.createElement('button');launch.id='tile-chooser-toggle';launch.ariaLabel=launch.title='Choose scene type';launch.setAttribute('aria-expanded','false');launch.innerHTML=multiHexIcon();
 const panel=document.createElement('section');panel.id='tile-chooser';panel.hidden=true;panel.ariaLabel='Expand this world';panel.innerHTML='<div class="tile-expand-heading"><span>Choose an empty hex</span><button aria-label="Close scene tray">×</button></div><div class="tile-options" hidden></div><p class="tile-preview-status" role="status">Click an outlined hex in the world.</p><button class="add-tile" hidden>Place here</button>';
 const picker=document.createElement('section');picker.id='scene-generator-picker';picker.hidden=true;picker.setAttribute('aria-label','Scene generators');
 const sceneType=document.createElement('div');sceneType.id='current-scene-type';sceneType.textContent='Ranch';
 document.body.append(panel,picker,sceneType);const mainBar=document.querySelector('#panel');(mainBar||document.body).prepend(launch);
 let generator=SCENE_GENERATORS[0],garden=gardenSettings(),settingsByType={};
 const settings=()=>settingsByType[type]??=placementSettings(type);
 const facet=document.createElement('label');facet.className='placement-facet';facet.innerHTML=uiIcon('largeHex')+'<select aria-label="Scene facet"></select>';panel.append(facet);
 const axes=document.createElement('div');axes.className='placement-axes';panel.append(axes);
 const advanced=document.createElement('button');advanced.className='placement-advanced';advanced.innerHTML=uiIcon('sliders');advanced.title=advanced.ariaLabel='Placement settings';advanced.setAttribute('aria-expanded','false');panel.append(advanced);
 const details=document.createElement('aside');details.className='placement-details';details.hidden=true;details.setAttribute('aria-label','Placement settings');panel.append(details);
 advanced.onclick=()=>{details.hidden=!details.hidden;advanced.setAttribute('aria-expanded',String(!details.hidden));};
 let rebuildTimer;
 function schedulePreview(){token++;clearAsset();loading=true;setCardsBusy(true);clearTimeout(rebuildTimer);rebuildTimer=setTimeout(()=>{if(opened)load(type,preferredSlot());},220);}
 function updateSetting(key,value){settingsByType[type]=placementSettings(type,{...settings(),[key]:value});if(type==='crop')garden=settingsByType[type];for(const input of panel.querySelectorAll('[data-setting="'+key+'"]'))input.value=settings()[key];schedulePreview();}
 function renderControls(){if(!type)return;const config=settings(),select=facet.querySelector('select');select.replaceChildren();const choices=type==='moon'?SCIENCE_BASE_FACETS:type==='crop'?[['kitchen','Kitchen garden'],['flowers','Flower garden'],['berries','Berry garden'],['mixed','Mixed garden']]:TILE_CHOICES.filter(([id])=>generator.tiles.includes(id));for(const [value,text]of choices){const option=document.createElement('option');option.value=value;option.textContent=text;select.append(option);}select.value=type==='moon'?config.planet:type==='crop'?config.facet:type;select.title=select.selectedOptions[0]?.textContent||generator.label;facet.title=select.title;select.onchange=()=>{if(type==='moon'){updateSetting('planet',select.value);facet.title=select.selectedOptions[0].textContent;}else if(type==='crop'){updateSetting('facet',select.value);facet.title=select.selectedOptions[0].textContent;}else{type=select.value;renderControls();schedulePreview();}};
 axes.replaceChildren();details.replaceChildren();const title=document.createElement('strong');title.textContent=generator.label+' settings';details.append(title);const note=document.createElement('p');note.textContent=type==='moon'?'Cargo changes pallet count; layout variation changes the seeded base. Colony size is unchanged.':'These settings apply to the new tile. Existing terrain and placed scenes stay fixed.';details.append(note);
 for(const axis of placementAxes(type)){const label=document.createElement('label');label.title=axis.label;label.innerHTML='<span aria-hidden="true">'+uiIcon(axis.icons[0])+'</span><input type="range" data-setting="'+axis.key+'" aria-label="'+axis.label+'" min="'+axis.min+'" max="'+axis.max+'" value="'+config[axis.key]+'"><span aria-hidden="true">'+uiIcon(axis.icons[1])+'</span>';label.querySelector('input').oninput=e=>updateSetting(axis.key,e.target.value);axes.append(label);const expanded=document.createElement('label');expanded.textContent=axis.label;const input=label.querySelector('input').cloneNode();input.oninput=e=>updateSetting(axis.key,e.target.value);expanded.append(input);details.append(expanded);}
 if(type==='moon'){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=config.auroraConstruction;input.setAttribute('aria-label','Aurora construction pad');input.onchange=()=>updateSetting('auroraConstruction',input.checked);label.append(input,document.createTextNode('Aurora construction pad'));details.append(label);const help=document.createElement('p');help.textContent='Second pad with a partially built USS AURORA and completed name. Requires an 80 m tile. Monthly ferry stays operational.';details.append(help);}
 for(const b of options.children)b.hidden=b.dataset.type!==type;
 }
 for(const g of SCENE_GENERATORS){const button=document.createElement('button');button.textContent=g.label;button.title='Preview '+g.label+' in the tray';button.dataset.generator=g.id;button.setAttribute('aria-pressed',String(g===generator));button.onclick=()=>{generator=g;picker.hidden=true;launch.setAttribute('aria-expanded','false');if(!opened)open();else{token++;clearAsset();type=null;add.hidden=true;}sceneType.textContent=g.label;for(const b of picker.children)b.setAttribute('aria-pressed',String(b.dataset.generator===g.id));type=g.tiles[0];renderControls();options.hidden=false;heading.textContent=g.label;status.textContent='Adjust the mini scene, then drag it onto an empty hex.';document.body.dataset.tileTray='open';launch.setAttribute('aria-expanded','false');positionTitle();if(slots.length)load(g.tiles[0],preferredSlot());};picker.append(button);}
const options=panel.querySelector('.tile-options'),status=panel.querySelector('[role=status]'),add=panel.querySelector('.add-tile'),heading=panel.querySelector('.tile-expand-heading span');
 const tooltips=attachTrayTooltips();
 let openingView=null,opened=false,slots=[],asset=null,selected=-1,type=null,token=0,drag=null,press=null,loading=false;
 function positionTitle(){const bar=opened?panel:document.querySelector('#panel');if(!bar)return;const rect=bar.getBoundingClientRect();sceneType.style.left=rect.left+12+'px';sceneType.style.bottom=Math.max(0,window.innerHeight-rect.top+7)+'px';sceneType.style.width=Math.max(0,rect.width-55)+'px';sceneType.style.transform='none';}
 const resize=typeof ResizeObserver==='undefined'?null:new ResizeObserver(positionTitle);resize?.observe(panel);if(mainBar)resize?.observe(mainBar);window.addEventListener('resize',positionTitle);positionTitle();
 const touches=new Set();
 const ray=new T.Raycaster(),pointer=new T.Vector2();
 const dispose=o=>{scene.remove(o);o.traverse(n=>{n.geometry?.dispose();n.material?.dispose();});};
 function clearAsset(){livePreview?.clear();delete canvas.dataset.tilePreview;if(asset){scene.remove(asset.group);asset.dispose();asset=null;}}
 function close(placed=false){cancelDrag();tooltips.hide();if(!placed&&openingView){camera.position.copy(openingView.position);orbit.target.copy(openingView.target);orbit.update();}openingView=null;details.hidden=true;advanced.setAttribute('aria-expanded','false');clearTimeout(rebuildTimer);(mainBar||document.body).prepend(launch);opened=false;token++;clearAsset();slots.forEach(s=>dispose(s.object));slots=[];panel.hidden=true;picker.hidden=true;document.body.dataset.tileTray='closed';sceneType.textContent='Ranch';launch.setAttribute('aria-expanded','false');drag=null;press=null;positionTitle();}
 function hit(e){const r=canvas.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)return -1;pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);camera.updateMatrixWorld();scene.updateMatrixWorld(true);ray.setFromCamera(pointer,camera);return ray.intersectObjects(slots.map(s=>s.surface),false)[0]?.object.userData.slot??-1;}

 let livePreview,viewFrame=0;
 function preferredSlot(){camera.updateMatrixWorld();let best=0,score=Infinity;slots.forEach((s,i)=>{const p=new T.Vector3().fromBufferAttribute(s.surface.geometry.attributes.position,0).project(camera),cost=Math.abs(p.x)+Math.abs(p.y)*1.3+(p.z>1?100:0);if(cost<score){best=i;score=cost;}});return best;}
 function showPreview(next,id){livePreview??=createLiveTrayPreview();const card=[...options.children].find(b=>b.dataset.type===id);livePreview.set(next,card);}
 function highlight(i){slots.forEach((s,j)=>s.line.material.color.set(j===i?'#b84931':'#798269'));}
 function setCardsBusy(value){for(const card of options.children){card.disabled=value;card.setAttribute('aria-busy',String(value));}}
 async function load(id,i,place=false){const request=++token;clearAsset();type=id;renderControls();selected=i;loading=true;setCardsBusy(true);add.hidden=true;status.textContent=place?'Placing scene…':'Generating mini preview…';for(const b of options.children)b.setAttribute('aria-pressed',String(b.dataset.type===id));try{const next=await preview(id,i,{...settings()},{trayOnly:true});if(!opened||request!==token){next.dispose();return;}asset=next;if(!place)showPreview(next,id);canvas.dataset.tilePreview=JSON.stringify({type:id,slot:i,location:'tray',settings:{...settings()},children:next.group.children.length});loading=false;setCardsBusy(false);if(place){await commit();return;}status.textContent=next.warning||'Drag the live scene onto an empty hex. Scroll to zoom; middle-drag to orbit.';}catch(e){if(request===token){loading=false;setCardsBusy(true);clearAsset();status.textContent=e.message;}}}
 const ghost=document.createElement('div');ghost.id='scene-drag-ghost';ghost.setAttribute('aria-hidden','true');ghost.hidden=true;document.body.append(ghost);
 function cancelDrag(restore=true){cancelAnimationFrame(viewFrame);viewFrame=0;if(restore&&drag?.view){camera.position.copy(drag.view.position);orbit.target.copy(drag.view.target);orbit.update();}if(drag?.button&&livePreview?.canvas.parentElement===ghost)drag.button.prepend(livePreview.canvas);drag=null;ghost.hidden=true;slots.forEach(s=>s.object.visible=false);highlight(-1);}
 function frameDropTargets(){const box=new T.Box3();for(const slot of slots)box.expandByObject(slot.object);const center=box.getCenter(new T.Vector3()),radius=box.getSize(new T.Vector3()).length()/2,direction=camera.position.clone().sub(orbit.target).normalize(),angle=Math.min(camera.fov*Math.PI/360,Math.atan(Math.tan(camera.fov*Math.PI/360)*camera.aspect)),destination=center.clone().addScaledVector(direction,Math.min(orbit.maxDistance,radius/Math.sin(angle)*1.05)),from=camera.position.clone(),target=orbit.target.clone(),start=performance.now();
 const move=now=>{if(!drag)return;const t=matchMedia('(prefers-reduced-motion: reduce)').matches?1:Math.min(1,(now-start)/200),ease=t*t*(3-2*t);camera.position.lerpVectors(from,destination,ease);orbit.target.lerpVectors(target,center,ease);orbit.update();if(drag.last)highlight(hit(drag.last));if(t<1)viewFrame=requestAnimationFrame(move);};viewFrame=requestAnimationFrame(move);}
 function moveGhost(e){ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';}
 async function commit(){if(!asset||loading)return;const apply=asset.commit;try{const placed=asset,placing=apply();asset=null;placed.dispose();close(true);await placing;}catch(e){document.querySelector('#error').textContent=e.message;}}
 for(const [id,label]of TILE_CHOICES){const b=document.createElement('button');const caption=document.createElement('span');caption.textContent=label;b.setAttribute('aria-label','Drag '+label+' mini scene onto an empty hex');b.append(caption);b.dataset.type=id;b.title='Drag '+label+' onto an empty hex to place';b.addEventListener('contextmenu',e=>e.preventDefault());b.onclick=()=>{if(loading)return;status.textContent='Drag this mini scene onto an empty hex to place it.';};
 b.addEventListener('pointerdown',e=>{if(loading||!asset||b.disabled||cameraOwnsPointer(e)||e.altKey||e.button!==0||touches.size>1)return;drag={id:e.pointerId,type:id,x:e.clientX,y:e.clientY,moved:false,button:b,view:{position:camera.position.clone(),target:orbit.target.clone()}};b.setPointerCapture(e.pointerId);tooltips.hide();});
 b.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;if(e.shiftKey||e.ctrlKey||e.metaKey||e.altKey||(e.buttons&6)){cancelDrag();return;}if(!drag.moved&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7){drag.moved=true;frameDropTargets();}if(drag.moved){drag.last={clientX:e.clientX,clientY:e.clientY};if(livePreview?.canvas.parentElement!==ghost)ghost.append(livePreview.canvas);ghost.hidden=false;moveGhost(e);slots.forEach(s=>s.object.visible=true);highlight(hit(e));status.textContent='Drop onto an outlined hex to place. Drop elsewhere to cancel.';}});
 b.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const d=drag,i=hit(e),valid=d.moved&&i>=0&&document.elementFromPoint(e.clientX,e.clientY)===canvas&&e.clientY<panel.getBoundingClientRect().top&&!cameraOwnsPointer(e)&&!e.altKey;cancelDrag(!valid);if(valid){slots[i].object.visible=true;highlight(i);if(asset?.slot===i){commit();}else load(id,i,true);}else status.textContent=d.moved?'Drop cancelled. Adjust the mini scene or drag again.':'Drag this mini scene onto an empty hex to place it.';});
 b.addEventListener('pointercancel',()=>{cancelDrag();status.textContent='Drag cancelled. Your board is unchanged.';});b.addEventListener('lostpointercapture',()=>{if(drag)cancelDrag();});options.append(b);}
 function open(){if(!allowed())return;openingView={position:camera.position.clone(),target:orbit.target.clone()};panel.prepend(launch);opened=true;selected=-1;type=null;panel.hidden=false;options.hidden=true;add.hidden=true;heading.textContent='Choose an empty hex';status.textContent='Choose a scene, adjust its mini preview, then drag it onto the board.';launch.setAttribute('aria-expanded','true');const {tiles,diameter,heightAt}=getBoard();
  slots=frontier(tiles,diameter).map((cell,index)=>{const center=tileCenter(cell.q,cell.r,diameter),points=[],vertices=[],object=new T.Group();const p=(a)=>{const edge=Math.floor(a/(Math.PI/3)),t=a/(Math.PI/3)-edge,b=edge*Math.PI/3,c=b+Math.PI/3;const x=center.x+(Math.sin(b)*(1-t)+Math.sin(c)*t)*diameter/2,z=center.z+(Math.cos(b)*(1-t)+Math.cos(c)*t)*diameter/2;return new T.Vector3(x*.1,heightAt(x,z)*.1+.045,z*.1);};const middle=new T.Vector3(center.x*.1,heightAt(center.x,center.z)*.1+.045,center.z*.1);for(let e=0;e<48;e++){const a=p(e*Math.PI/24),b=p((e+1)*Math.PI/24);points.push(a);vertices.push(...middle.toArray(),...a.toArray(),...b.toArray());}const surface=new T.Mesh(new T.BufferGeometry().setAttribute('position',new T.Float32BufferAttribute(vertices,3)),new T.MeshBasicMaterial({color:'#e9e2c8',transparent:true,opacity:.18,side:T.DoubleSide,depthWrite:false}));surface.userData.slot=index;const line=new T.LineLoop(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color:'#798269',depthTest:false}));line.raycast=()=>{};object.add(surface,line);object.visible=false;scene.add(object);return {object,surface,line};});
 }
 launch.onclick=()=>{if(!allowed())return;picker.hidden=!picker.hidden;const rect=launch.getBoundingClientRect();picker.style.left=Math.max(10,Math.min(rect.left,window.innerWidth-210))+'px';picker.style.bottom=Math.max(10,window.innerHeight-rect.top+8)+'px';launch.setAttribute('aria-expanded',String(!picker.hidden));};panel.querySelector('.tile-expand-heading button').onclick=()=>close();add.innerHTML=uiIcon('largeHex').replace('</svg>','<path d="M12 7v10M7 12h10"/></svg>');add.title=add.ariaLabel='Place here';add.onclick=commit;
 panel.querySelector('.tile-expand-heading button').title='Close scene tray';
 const touchDown=e=>{if(e.pointerType==='touch'){touches.add(e.pointerId);if(touches.size>1)cancelDrag();}};
 const touchUp=e=>touches.delete(e.pointerId);
 const keydown=e=>{if(e.key==='Escape'){cancelDrag();close();}};
 window.addEventListener('pointerdown',touchDown,true);window.addEventListener('pointerup',touchUp,true);window.addEventListener('pointercancel',touchUp,true);window.addEventListener('keydown',keydown);
 return {close,get opened(){return opened;},dispose(){close();livePreview?.dispose();resize?.disconnect();window.removeEventListener('resize',positionTitle);window.removeEventListener('pointerdown',touchDown,true);window.removeEventListener('pointerup',touchUp,true);window.removeEventListener('pointercancel',touchUp,true);window.removeEventListener('keydown',keydown);ghost.remove();tooltips.dispose();panel.remove();launch.remove();picker.remove();sceneType.remove();}};
}

const liveTrayStyle=document.createElement('style');liveTrayStyle.textContent='#tile-chooser .tile-options .live-tray-canvas{display:block;width:100%;height:100%;pointer-events:auto;touch-action:none;background:transparent;border-radius:8px}#tile-chooser .tile-options button:has(.live-tray-canvas){background:transparent!important;border-color:var(--app-border)!important}#tile-chooser .live-tray-canvas+span{display:none}#scene-drag-ghost .live-tray-canvas{width:100%;height:100%;pointer-events:none}';document.head.append(liveTrayStyle);
